 public static GameObject Rect(string name,Transform parent,Vector2 size,Vector2 pos){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(.5f,.5f);r.sizeDelta=size;r.anchoredPosition=pos;return g;}
 public static TMP_Text Text(string name,Transform parent,string text,Vector2 size,Vector2 pos,int font=28){var g=Rect(name,parent,size,pos);var t=g.AddComponent<TextMeshProUGUI>();t.font=TMP_Settings.defaultFontAsset;t.fontSize=font;t.text=text;t.color=Color.white;t.raycastTarget=false;t.alignment=TextAlignmentOptions.Center;t.enableAutoSizing=true;t.fontSizeMin=font*.8f;t.fontSizeMax=font;return t;}
 public static ButtonManager Button(Transform parent,string text,string key,Vector2 pos,Vector2? size=null){var s=size??new Vector2(540,64);var g=Rect(key+" Button",parent,s,pos);var image=g.AddComponent<Image>();image.color=new Color(.035f,.19f,.19f);g.AddComponent<Button>().transition=Selectable.Transition.None;var label=Text("Caption",g.transform,text,s-new Vector2(18,8),Vector2.zero,26);var b=g.AddComponent<ButtonManager>();b.autoFitContent=false;b.useLocalization=false;b.useSounds=false;b.checkForDoubleClick=false;b.useUINavigation=true;b.navigationMode=Navigation.Mode.Explicit;b.normalTextObj=(TextMeshProUGUI)label;b.textSize=26;b.buttonText=text;var a=g.AddComponent<SportsMenuAction>();a.action=key;a.button=b;g.AddComponent<BilliardsButtonVisual>().surface=image;return b;}
 public static GameObject Page(string name,Transform parent,string title,string subtitle=""){var p=Rect(name,parent,new Vector2(1920,1080),Vector2.zero);p.AddComponent<Image>().color=new Color(.004f,.012f,.019f,.7f);var card=Rect("Card",p.transform,new Vector2(1460,900),Vector2.zero);card.AddComponent<Image>().color=new Color(.014f,.038f,.048f,.97f);var line=Rect("Accent",p.transform,new Vector2(1460,6),new Vector2(0,447));line.AddComponent<Image>().color=new Color(.15f,.8f,.7f);Text("Title",p.transform,title,new Vector2(1350,78),new Vector2(0,365),48);Text("Subtitle",p.transform,subtitle,new Vector2(1320,72),new Vector2(0,285),24).color=new Color(.6f,.78f,.8f);return p;}
 public static TMP_InputField Name(Transform parent,string label,string value,Vector2 pos){Text(label,parent,label,new Vector2(520,40),pos+new Vector2(0,45),24);var g=Rect(label+" Input",parent,new Vector2(520,58),pos);g.AddComponent<Image>().color=new Color(.05f,.11f,.14f);var viewport=Rect("Viewport",g.transform,new Vector2(495,56),Vector2.zero);viewport.AddComponent<RectMask2D>();var t=Text("Name",viewport.transform,value,new Vector2(480,55),Vector2.zero,27);t.alignment=TextAlignmentOptions.MidlineLeft;var input=g.AddComponent<TMP_InputField>();input.textViewport=viewport.GetComponent<RectTransform>();input.textComponent=(TextMeshProUGUI)t;input.characterLimit=20;input.text=value;input.lineType=TMP_InputField.LineType.SingleLine;var heat=g.AddComponent<InputFieldManager>();heat.inputText=input;heat.processSubmit=false;return input;}
 public static Slider Slider(Transform parent,string label,Vector2 pos,float min,float max,float value){Text(label,parent,label,new Vector2(600,40),pos+new Vector2(0,48),25);var g=Rect(label+" Slider",parent,new Vector2(600,48),pos);var track=Rect("Track",g.transform,new Vector2(600,12),Vector2.zero);track.AddComponent<Image>().color=new Color(.05f,.18f,.2f);var handle=Rect("Handle",g.transform,new Vector2(24,0),Vector2.zero);var image=handle.AddComponent<Image>();image.color=new Color(.15f,.8f,.7f);var s=g.AddComponent<Slider>();s.minValue=min;s.maxValue=max;s.value=value;s.handleRect=handle.GetComponent<RectTransform>();s.targetGraphic=image;var heat=g.AddComponent<SliderManager>();heat.mainSlider=s;heat.saveValue=false;heat.invokeOnAwake=false;heat.useSounds=false;heat.showValue=true;heat.showPopupValue=false;heat.usePercent=max==100;heat.useRoundValue=max==100;var txt=Text("Value",g.transform,"",new Vector2(80,40),new Vector2(350,0),24);var so=new SerializedObject(heat);so.FindProperty("valueText").objectReferenceValue=txt;so.ApplyModifiedPropertiesWithoutUndo();return s;}
 public static void UpgradeMusic(SportsMenuView view){if(view.music!=null)return;var page=view.pages.FirstOrDefault(p=>p!=null&&p.name=="Settings");if(page==null)return;view.music=Slider(page.transform,"MUSIC VOLUME",new Vector2(-330,-215),0,100,55);EditorUtility.SetDirty(view);}
 public static void SettingsPage(SportsMenuView view,int index){var p=Page("Settings",view.transform,"SETTINGS","Shared Truck Sports / Billiards preferences • Audio previews immediately");view.pages[index]=p;view.master=Slider(p.transform,"MASTER VOLUME",new Vector2(-330,145),0,100,100);view.sfx=Slider(p.transform,"SFX VOLUME",new Vector2(-330,25),0,100,65);view.steering=Slider(p.transform,"CONTROLLER STEERING",new Vector2(-330,-95),.4f,2,1);view.music=Slider(p.transform,"MUSIC VOLUME",new Vector2(-330,-215),0,100,55);view.displayText=Button(p.transform,"WINDOWED","fullscreen",new Vector2(350,140),new Vector2(550,62)).normalTextObj;view.resolutionText=Button(p.transform,"RESOLUTION","resolution",new Vector2(350,40),new Vector2(550,62)).normalTextObj;view.vibrationText=Button(p.transform,"VIBRATION ON","vibration",new Vector2(350,-60),new Vector2(550,62)).normalTextObj;Text("Info",p.transform,"Master / SFX / steering / vibration are shared.\nEach sport keeps its own AI difficulty.",new Vector2(580,100),new Vector2(350,-180),22);Button(p.transform,"BACK","back",new Vector2(-320,-340));Button(p.transform,"SAVE / APPLY","save",new Vector2(320,-340));SportsCabUpgradeAuthoring.InstallSettings(view);}
 public static Canvas Canvas(){var g=new GameObject("Sports Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));var c=g.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;var s=g.GetComponent<CanvasScaler>();s.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;s.referenceResolution=new Vector2(1920,1080);s.matchWidthOrHeight=.5f;return c;}
 public static EventSystem Events(GameObject root){
 string path="Assets/TruckSports/Input/SportsUI.inputactions";Directory.CreateDirectory("Assets/TruckSports/Input");if(!File.Exists(path))File.Copy("Library/PackageCache/com.unity.inputsystem@21a28c3a6c83/InputSystem/Plugins/PlayerInput/DefaultInputActions.inputactions",path);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);
 var asset=AssetDatabase.LoadAssetAtPath<InputActionAsset>(path);var references=AssetDatabase.LoadAllAssetsAtPath(path).OfType<InputActionReference>().ToArray();InputActionReference Ref(string name)=>references.First(r=>r.action.actionMap.name=="UI"&&r.action.name==name);
 var g=new GameObject("Sports Event System",typeof(EventSystem));g.SetActive(false);var module=g.AddComponent<InputSystemUIInputModule>();module.actionsAsset=asset;module.point=Ref("Point");module.move=Ref("Navigate");module.submit=Ref("Submit");module.cancel=Ref("Cancel");module.leftClick=Ref("Click");module.rightClick=Ref("RightClick");module.middleClick=Ref("MiddleClick");module.scrollWheel=Ref("ScrollWheel");g.SetActive(true);var e=g.GetComponent<EventSystem>();root.AddComponent<BilliardsHostIsolation>().modeEventSystem=e;return e;}
